import java.util.*;
import java.io.*;

public class FlowNetworkSolver {
    static final int MAXN = 300;
    static final int MAXM = 65536;
    static final int INF = 1000000007;
    static final int[] dx = {-1, 0, 1, 0};
    static final int[] dy = {0, -1, 0, 1};

    static class Edge {
        int v, c;
        Edge(int v, int c) {
            this.v = v;
            this.c = c;
        }
    }

    static class FlowNetwork {
        int n, m, source, sink;
        List<Integer>[] e = new ArrayList[MAXN];
        Edge[] edge = new Edge[MAXM * 2];

        int[] capacity = new int[MAXN];
        int[] dist = new int[MAXN];
        int[] current = new int[MAXN];
        int[] parent = new int[MAXN];
        int path_length;

        int mCount;

        void initialize(int n, int s, int t) {
            this.n = n;
            this.mCount = 0;
            this.source = s;
            this.sink = t;
            for (int i = 0; i < n; i++) {
                e[i] = new ArrayList<>();
            }
        }

        void connect(int a, int b, int c) {
            edge[mCount] = new Edge(b, c);
            e[a].add(mCount);
            edge[mCount + 1] = new Edge(a, 0);
            e[b].add(mCount + 1);
            mCount += 2;
        }

        int RE(int i) {
            return i ^ 1;
        }

        void bfs() {
            Arrays.fill(capacity, 0, n, 0);
            Arrays.fill(dist, 0, n, n);
            dist[sink] = 0;
            Queue<Integer> q = new LinkedList<>();
            q.offer(sink);
            while (!q.isEmpty()) {
                int u = q.poll();
                for (int id : e[u]) {
                    int v = edge[id].v;
                    if (dist[v] == n && edge[RE(id)].c > 0) {
                        dist[v] = dist[u] + 1;
                        q.offer(v);
                    }
                }
            }
        }

        void retreat(int v) {
            capacity[dist[v]]--;
            dist[v] = n;
            for (int i = 0; i < e[v].size(); i++) {
                int id = e[v].get(i);
                Edge arc = edge[id];
                if (dist[v] > dist[arc.v] + 1 && arc.c > 0) {
                    dist[v] = dist[arc.v] + 1;
                    parent[v] = i;
                }
            }
            capacity[dist[v]]++;
        }

        int augment() {
            int flow = Integer.MAX_VALUE;
            int idx = -1;
            for (int i = 0; i < path_length; i++) {
                int id = e[parent[path[i]]].get(current[path[i]]);
                Edge arc = edge[id];
                if (arc.c < flow) {
                    flow = arc.c;
                    idx = i;
                }
            }
            for (int i = 0; i < path_length; i++) {
                int id = e[parent[path[i]]].get(current[path[i]]);
                edge[id].c -= flow;
                edge[RE(id)].c += flow;
            }
            path_length = idx;
            return flow;
        }

        int maxFlow() {
            int total = 0;
            bfs();
            Arrays.fill(current, 0, n, 0);
            path_length = 0;
            parent[source] = -1;
            int u = source;
            while (dist[source] != n) {
                if (u == sink) {
                    total += augment();
                    u = source;
                    continue;
                }
                boolean advanced = false;
                for (; current[u] < e[u].size(); ++current[u]) {
                    int id = e[u].get(current[u]);
                    Edge arc = edge[id];
                    if (dist[arc.v] == dist[u] - 1 && arc.c > 0) {
                        parent[arc.v] = id;
                        u = arc.v;
                        path_length++;
                        advanced = true;
                        break;
                    }
                }
                if (!advanced) {
                    if (capacity[dist[u]] == 1) break;
                    retreat(u);
                    if (u != source) {
                        path_length--;
                        u = edge[parent[u]].v;
                    }
                }
            }
            return total;
        }
    }

    static int MAXNODES = 12;
    static int INF = 1000000007;
    static int[] dx = {-1, 0, 1, 0};
    static int[] dy = {0, -1, 0, 1};

    static int n;
    static char[][] grid = new char[MAXNODES][MAXNODES];
    static char[][] result = new char[MAXNODES][MAXNODES];
    static int[][] dist_map = new int[MAXNODES][MAXNODES];
    static int[][] time_map = new int[MAXNODES][MAXNODES];

    static FlowNetwork fn = new FlowNetwork();

    static int nodeX(int i, int j) {
        return i * MAXNODES + j;
    }

    static int nodeY(int i, int j) {
        return MAXNODES * MAXNODES + i * MAXNODES + j;
    }

    static int sourceNode() {
        return MAXNODES * MAXNODES;
    }

    static int sinkNode() {
        return sourceNode() + 1;
    }

    static int totalNodes() {
        return sinkNode() + 1;
    }

    static void computeDistances(int size) {
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                dist_map[i][j] = INF;
            }
        }
        Queue<int[]> q = new LinkedList<>();
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (grid[i][j] == 'Z') {
                    q.offer(new int[]{i, j});
                    dist_map[i][j] = 0;
                }
            }
        }
        while (!q.isEmpty()) {
            int[] p = q.poll();
            int x = p[0], y = p[1];
            for (int k = 0; k < 4; k++) {
                int xx = x + dx[k], yy = y + dy[k];
                if (0 <= xx && xx < size && 0 <= yy && yy < size
                        && Character.isDigit(grid[xx][yy]) && dist_map[xx][yy] == INF) {
                    dist_map[xx][yy] = dist_map[x][y] + 1;
                    q.offer(new int[]{xx, yy});
                }
            }
        }
    }

    static void process(int size, int maxDist, int startX, int startY) {
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                time_map[i][j] = INF;
            }
        }
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{startX, startY});
        time_map[startX][startY] = 0;
        while (!q.isEmpty()) {
            int[] p = q.poll();
            int x = p[0], y = p[1];
            if (time_map[x][y] > maxDist) break;
            if (time_map[x][y] <= dist_map[x][y] && Character.isDigit(result[x][y]) && result[x][y] != '0') {
                fn.connect(nodeX(startX, startY), nodeY(x, y), 11);
            }
            if (time_map[x][y] >= dist_map[x][y]) continue;
            for (int k = 0; k < 4; k++) {
                int xx = x + dx[k], yy = y + dy[k];
                if (0 <= xx && xx < size && 0 <= yy && yy < size
                        && Character.isDigit(grid[xx][yy]) && time_map[xx][yy] == INF) {
                    time_map[xx][yy] = time_map[x][y] + 1;
                    q.offer(new int[]{xx, yy});
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int size = Integer.parseInt(st.nextToken());
        int maxDist = Integer.parseInt(st.nextToken());

        fn.initialize(totalNodes(), sourceNode(), sinkNode());

        for (int i = 0; i < size; i++) {
            String line = br.readLine();
            grid[i] = line.toCharArray();
            for (int j = 0; j < size; j++) {
                if (Character.isDigit(grid[i][j]) && grid[i][j] != '0') {
                    fn.connect(sourceNode(), nodeX(i, j), grid[i][j] - '0');
                }
            }
        }

        for (int i = 0; i < size; i++) {
            String line = br.readLine();
            result[i] = line.toCharArray();
            for (int j = 0; j < size; j++) {
                if (Character.isDigit(result[i][j]) && result[i][j] != '0') {
                    fn.connect(nodeY(i, j), sinkNode(), result[i][j] - '0');
                }
            }
        }

        computeDistances(size);
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (Character.isDigit(grid[i][j]) && grid[i][j] != '0') {
                    process(size, maxDist, i, j);
                }
            }
        }

        System.out.println(fn.maxFlow());
    }
}
